use std::sync::Arc;

use rodas5p_core::directed::{Interval, add_up, mul_up, sqrt_up};
use rodas5p_core::{CoreError, CoreResult};

use crate::problem::{OdeProblem, SparseLinearPart};

/// Build Gray-Scott 2D problem on periodic unit square with dimension $n = 2 N^2$.
///
/// Equations:
/// $u_t = D_u \Delta u - u v^2 + F (1 - u)$
/// $v_t = D_v \Delta v + u v^2 - (F + k) v$
///
/// Parameters:
/// $D_u = 2\times 10^{-3}$, $D_v = 10^{-3}$, $F = 0.04$, $k = 0.06$, on $t \in [0, 20]$.
/// A structural logarithmic-norm descriptor for the Gray-Scott problem
/// generated by [`gray_scott_2d_with_log_norm`]. Its grid size is private so
/// callers cannot mutate the dimension after construction.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct GrayScottLogNorm {
    n_grid: usize,
}

impl GrayScottLogNorm {
    pub fn grid_size(self) -> usize {
        self.n_grid
    }

    /// Outward upper bound for the unweighted Euclidean logarithmic norm of
    /// the full Gray-Scott Jacobian over componentwise state boxes.
    ///
    /// The periodic diffusion blocks are symmetric negative semidefinite, so
    /// their logarithmic norm is nonpositive. The remaining Jacobian is a
    /// direct sum of local 2x2 reaction blocks. For each box the symmetric
    /// block's largest eigenvalue is bounded with directed interval
    /// operations, and the maximum over all cells bounds the full operator.
    /// This is specific to this generated Gray-Scott structure; it is not a
    /// generic max-diagonal bound for arbitrary Jacobians.
    pub fn verified_log_norm_upper(
        self,
        u_tube: &[Interval],
        v_tube: &[Interval],
    ) -> CoreResult<f64> {
        let cells = self
            .n_grid
            .checked_mul(self.n_grid)
            .ok_or_else(|| CoreError::InvalidInput("Gray-Scott grid size overflow".into()))?;
        if u_tube.len() != cells || v_tube.len() != cells {
            return Err(CoreError::Dimension(
                "Gray-Scott tube must provide one u/v interval per grid cell".into(),
            ));
        }

        let f = Interval::point(0.04)?;
        let fk = Interval::point(0.04 + 0.06)?;
        let half = Interval::point(0.5)?;
        let mut upper = f64::NEG_INFINITY;
        for (&u_raw, &v_raw) in u_tube.iter().zip(v_tube) {
            // Interval fields are public, so reconstruct to reject forged
            // NaN, infinite, or reversed bounds before arithmetic.
            let u = Interval::new(u_raw.lo, u_raw.hi)?;
            let v = Interval::new(v_raw.lo, v_raw.hi)?;
            let v2 = v.mul(v)?;
            let uv = u.mul(v)?;
            let a = Interval::point(0.0)?.sub(v2)?.sub(f)?;
            let d = uv.scale(2.0)?.sub(fk)?;
            let trace_half_upper = a.add(d)?.mul(half)?.hi;
            let delta_half = a.sub(d)?.mul(half)?;
            let offdiag_half = v2.sub(uv.scale(2.0)?)?.mul(half)?;
            let delta_mag = delta_half.mag();
            let offdiag_mag = offdiag_half.mag();
            let radicand_upper = add_up(
                mul_up(delta_mag, delta_mag)?,
                mul_up(offdiag_mag, offdiag_mag)?,
            )?;
            let block_upper = add_up(trace_half_upper, sqrt_up(radicand_upper)?)?;
            upper = upper.max(block_upper);
        }
        if upper.is_finite() {
            Ok(upper)
        } else {
            Err(CoreError::NonFinite(
                "Gray-Scott logarithmic norm bound is non-finite".into(),
            ))
        }
    }
}

/// Build Gray-Scott 2D problem and its matching structural logarithmic-norm
/// descriptor.
pub fn gray_scott_2d_with_log_norm(
    n_grid: usize,
) -> CoreResult<(OdeProblem, Vec<f64>, GrayScottLogNorm)> {
    if n_grid < 2 {
        return Err(CoreError::Dimension(
            "gray-scott-2d requires grid size >= 2".into(),
        ));
    }
    let n2 = n_grid * n_grid;
    let n = 2 * n2;
    let dx = 1.0 / (n_grid as f64);
    let inv_dx2 = 1.0 / (dx * dx);

    const D_U: f64 = 2.0e-3;
    const D_V: f64 = 1.0e-3;
    const F: f64 = 0.04;
    const K: f64 = 0.06;

    // Build initial condition
    let mut y0 = vec![0.0f64; n];
    for j in 0..n_grid {
        let y_coord = (j as f64 + 0.5) * dx;
        let dy = y_coord - 0.5;
        for i in 0..n_grid {
            let x_coord = (i as f64 + 0.5) * dx;
            let dx_c = x_coord - 0.5;
            let dist_sq = dx_c * dx_c + dy * dy;
            let bump = 0.25 * (-100.0 * dist_sq).exp();
            let idx = i + j * n_grid;
            y0[idx] = 1.0 - bump; // u
            y0[n2 + idx] = bump; // v
        }
    }

    // Helper to evaluate 5-point Laplacian on periodic grid
    let laplacian = move |vals: &[f64], out: &mut [f64]| {
        for j in 0..n_grid {
            let j_up = if j + 1 < n_grid { j + 1 } else { 0 };
            let j_down = if j > 0 { j - 1 } else { n_grid - 1 };
            for i in 0..n_grid {
                let i_right = if i + 1 < n_grid { i + 1 } else { 0 };
                let i_left = if i > 0 { i - 1 } else { n_grid - 1 };
                let idx = i + j * n_grid;
                let c = vals[idx];
                let l = vals[i_left + j * n_grid];
                let r = vals[i_right + j * n_grid];
                let u = vals[i + j_up * n_grid];
                let d = vals[i + j_down * n_grid];
                out[idx] = (l + r + u + d - 4.0 * c) * inv_dx2;
            }
        }
    };

    // Full RHS callback
    let rhs_lap = laplacian;
    let rhs = Arc::new(move |_t: f64, y: &[f64], out: &mut [f64]| {
        let (u, v) = y.split_at(n2);
        let (out_u, out_v) = out.split_at_mut(n2);

        let mut lap_u = vec![0.0f64; n2];
        let mut lap_v = vec![0.0f64; n2];
        rhs_lap(u, &mut lap_u);
        rhs_lap(v, &mut lap_v);

        for i in 0..n2 {
            let ui = u[i];
            let vi = v[i];
            let uv2 = ui * vi * vi;
            out_u[i] = D_U * lap_u[i] - uv2 + F * (1.0 - ui);
            out_v[i] = D_V * lap_v[i] + uv2 - (F + K) * vi;
        }
        Ok(())
    });

    // JVP callback
    let jvp_lap = laplacian;
    let jvp = Arc::new(move |_t: f64, y: &[f64], delta: &[f64], out: &mut [f64]| {
        let (u, v) = y.split_at(n2);
        let (du, dv) = delta.split_at(n2);
        let (out_u, out_v) = out.split_at_mut(n2);

        let mut lap_du = vec![0.0f64; n2];
        let mut lap_dv = vec![0.0f64; n2];
        jvp_lap(du, &mut lap_du);
        jvp_lap(dv, &mut lap_dv);

        for i in 0..n2 {
            let ui = u[i];
            let vi = v[i];
            let dui = du[i];
            let dvi = dv[i];
            // d/d(u,v) [-u v^2 + F(1-u)] * (du, dv) = -v^2 du - 2 u v dv - F du
            out_u[i] = D_U * lap_du[i] - vi * vi * dui - 2.0 * ui * vi * dvi - F * dui;
            // d/d(u,v) [u v^2 - (F+k)v] * (du, dv) = v^2 du + 2 u v dv - (F+k) dv
            out_v[i] = D_V * lap_dv[i] + vi * vi * dui + 2.0 * ui * vi * dvi - (F + K) * dvi;
        }
        Ok(())
    });

    // Build sparse linear part A = blockdiag(D_u Lap - F I, D_v Lap - (F + k) I)
    let mut col_ptr = Vec::with_capacity(n + 1);
    let mut row_idx = Vec::with_capacity(10 * n);
    let mut values = Vec::with_capacity(10 * n);

    col_ptr.push(0);

    // Block 1: u block (columns 0..n2)
    for j in 0..n_grid {
        let j_up = if j + 1 < n_grid { j + 1 } else { 0 };
        let j_down = if j > 0 { j - 1 } else { n_grid - 1 };
        for i in 0..n_grid {
            let i_right = if i + 1 < n_grid { i + 1 } else { 0 };
            let i_left = if i > 0 { i - 1 } else { n_grid - 1 };
            let col = i + j * n_grid;

            // Collect nonzeros in column col for u block
            // Entries in row idx:
            // diagonal: col
            // left: i_left + j * n_grid
            // right: i_right + j * n_grid
            // down: i + j_down * n_grid
            // up: i + j_up * n_grid
            let mut entries: Vec<(usize, f64)> = Vec::new();
            let diag_val = D_U * (-4.0 * inv_dx2) - F;
            let off_val = D_U * inv_dx2;

            entries.push((col, diag_val));
            // Coincident periodic neighbors (N=2) contribute twice.
            entries.push((i_left + j * n_grid, off_val));
            entries.push((i_right + j * n_grid, off_val));
            entries.push((i + j_down * n_grid, off_val));
            entries.push((i + j_up * n_grid, off_val));

            entries.sort_by_key(|&(r, _)| r);
            let column_start = row_idx.len();
            for (r, v) in entries {
                if row_idx.len() > column_start && row_idx.last() == Some(&r) {
                    *values.last_mut().expect("entry in current column") += v;
                } else {
                    row_idx.push(r);
                    values.push(v);
                }
            }
            col_ptr.push(row_idx.len());
        }
    }

    // Block 2: v block (columns n2..n)
    for j in 0..n_grid {
        let j_up = if j + 1 < n_grid { j + 1 } else { 0 };
        let j_down = if j > 0 { j - 1 } else { n_grid - 1 };
        for i in 0..n_grid {
            let i_right = if i + 1 < n_grid { i + 1 } else { 0 };
            let i_left = if i > 0 { i - 1 } else { n_grid - 1 };
            let col = i + j * n_grid;

            let mut entries: Vec<(usize, f64)> = Vec::new();
            let diag_val = D_V * (-4.0 * inv_dx2) - (F + K);
            let off_val = D_V * inv_dx2;

            entries.push((n2 + col, diag_val));
            // Coincident periodic neighbors (N=2) contribute twice.
            entries.push((n2 + i_left + j * n_grid, off_val));
            entries.push((n2 + i_right + j * n_grid, off_val));
            entries.push((n2 + i + j_down * n_grid, off_val));
            entries.push((n2 + i + j_up * n_grid, off_val));

            entries.sort_by_key(|&(r, _)| r);
            let column_start = row_idx.len();
            for (r, v) in entries {
                if row_idx.len() > column_start && row_idx.last() == Some(&r) {
                    *values.last_mut().expect("entry in current column") += v;
                } else {
                    row_idx.push(r);
                    values.push(v);
                }
            }
            col_ptr.push(row_idx.len());
        }
    }

    let sparse_a = SparseLinearPart::new(n, n, col_ptr, row_idx, values)?;

    // Nonlinear callback N(t, y) = [-u v^2 + F, u v^2]^T
    let nonlinear_n = Arc::new(move |_t: f64, y: &[f64], out: &mut [f64]| {
        let (u, v) = y.split_at(n2);
        let (out_u, out_v) = out.split_at_mut(n2);
        for i in 0..n2 {
            let uv2 = u[i] * v[i] * v[i];
            out_u[i] = -uv2 + F;
            out_v[i] = uv2;
        }
        Ok(())
    });

    let problem = OdeProblem::new(
        format!("gray-scott-2d-n{n_grid}"),
        n,
        rhs,
        None,
        None,
        Some(jvp),
        None,
        true,
        None,
        None,
    )?
    .with_linear_part(sparse_a, nonlinear_n)?;

    Ok((problem, y0, GrayScottLogNorm { n_grid }))
}

/// Build Gray-Scott 2D problem on periodic unit square with dimension $n = 2 N^2$.
pub fn gray_scott_2d(n_grid: usize) -> CoreResult<(OdeProblem, Vec<f64>)> {
    let (problem, y0, _log_norm) = gray_scott_2d_with_log_norm(n_grid)?;
    Ok((problem, y0))
}
